          "explanation": "Cấu trúc 'hire someone to do something' mang nghĩa 'thuê ai đó làm việc gì' (dùng to-infinitive chỉ mục đích mang nghĩa chủ động). Phía sau có tân ngữ 'our company's financial assets' nên hành động mang tính chủ động. Do đó dạng động từ nguyên mẫu có to 'to evaluate' (A) là đáp án đúng."
