          "explanation": "Chỗ trống nằm giữa trợ động từ 'have' và quá khứ phân từ 'increased' (thì hiện tại hoàn thành). Vị trí này cần một trạng từ để bổ nghĩa cho động từ. Xét về mối quan hệ nhân quả giữa hai mệnh đề: vế trước mở rộng thị trường quảng cáo, dẫn đến vế sau doanh số bán hàng tăng lên. Trạng từ 'consequently' (do đó, kết quả là, vì thế) diễn tả chính xác mối quan hệ kết quả này. Do đó chọn (B)."
