          "analysis": "Phân tích câu:\n* Costpa Analytics Ltd.: Công ty TNHH Phân tích Costpa (Danh từ riêng chỉ tên doanh nghiệp làm chủ ngữ)\n* has made successful investments: đã thực hiện các khoản đầu tư thành công (Động từ thì hiện tại hoàn thành + Cụm danh từ làm tân ngữ)\n* in two emerging data companies: vào hai công ty dữ liệu đang mới nổi (Cụm giới từ chỉ đối tượng nhận đầu tư)\n\nCấu trúc:\n* make investments in (v phr): thực hiện đầu tư vốn vào một dự án hoặc doanh nghiệp\n* emerging companies (n phr): các công ty mới nổi, đang trên đà phát triển mạnh mẽ"
