          "name": "Phối hợp thì với Mệnh đề thời gian (When / Before / After / Once / As soon as / By the time)",
          "structure": "When / Once / As soon as / Before + S + V(hiện tại đơn), S + WILL + V(nguyên mẫu)",
          "usage": "Trong mệnh đề chỉ thời gian ở tương lai (sau when, once, as soon as, before, until), KHÔNG dùng will mà chia Hiện tại đơn!",
          "exampleEn": "Once the shipment arrives, we will notify the warehouse manager.",
          "exampleVi": "Ngay khi lô hàng đến, chúng tôi sẽ thông báo cho quản lý kho."
