          "explanation": "Chủ ngữ là 'The release' (Việc phát hành) - đây là vật nên động từ phải ở dạng bị động. 'will be delayed' (sẽ bị trì hoãn) là dạng bị động duy nhất.",
          "analysis": "Phân tích câu:\n* The release: Việc phát hành / công bố chính thức (Danh từ chính làm chủ ngữ)\n* of the earnings report: của bản báo cáo kết quả thu nhập (Cụm giới từ bổ nghĩa cho The release)\n* will be delayed: sẽ bị tạm hoãn lại (Động từ chia thì tương lai đơn ở thể bị động)\n* until the latest company figures are ready: cho đến khi các số liệu mới nhất của công ty được hoàn tất sẵn sàng (Mệnh đề trạng ngữ chỉ thời gian bắt đầu bằng until)\n\nCấu trúc:\n* earnings report (n phr): báo cáo thu nhập / lợi nhuận tài chính.\n* be delayed until + S + V: bị trì hoãn cho đến khi điều gì hoàn tất."
