          "correctAnswer": "D",
          "questionTranslation": "Việc bảo dưỡng thiết bị sưởi ấm của bạn đúng cách đảm bảo rằng các sự cố nhỏ có thể được khắc phục trước khi chúng trở nên nghiêm trọng.",
