          "questionTranslation": "Những nhân viên có thâm niên làm việc trên một năm có thể nộp đơn xin hỗ trợ học phí nếu họ muốn theo đuổi một bằng cấp học thuật.",
          "explanation": "Ở đầu câu, trước cụm giới từ chỉ đặc điểm 'with more than a year of employment' và tương ứng với đại từ số nhiều 'they' ở mệnh đề sau, ta dùng đại từ chỉ định số nhiều 'Those' để mang nghĩa tổng quát 'Những người mà...' ('Those with...' = 'Those who have...'). Vì vậy, (A) Those là đáp án chính xác.",
          "analysis": "Phân tích cấu trúc câu theo cụm:\n* Those with more than a year of employment: Những ai/những nhân viên có trên một năm làm việc (Chủ ngữ)\n* can apply for tuition assistance: có thể đăng ký xin hỗ trợ học phí (Vị ngữ chính)\n* if they wish to pursue an academic degree: nếu họ mong muốn theo học lấy bằng cấp đại học/sau đại học.\n\nCấu trúc ngữ pháp cần nhớ:\n* Those who + V / Those with + N: Những người mà... (cấu trúc chỉ nhóm người nói chung trong văn bản quy định, thông báo)."
