          "explanation": "Hai mệnh đề chỉ nguyên nhân - kết quả: 'Mưa được dự báo vào cuối tuần này, VÌ VẬY chuyến dã ngoại... sẽ bị hoãn'. Liên từ 'so' (vì vậy) là phù hợp nhất.",
          "analysis": "Phân tích câu:\n* Rain is predicted: Mưa được dự báo (Cụm chủ ngữ và động từ chia thể bị động thì hiện tại đơn)\n* this weekend: vào dịp cuối tuần này (Cụm danh từ chỉ thời gian làm trạng ngữ)\n* so the office picnic: vì vậy buổi dã ngoại của văn phòng (Liên từ chỉ kết quả + Cụm danh từ làm chủ ngữ mệnh đề sau)\n* will have to be postponed: sẽ phải bị hoãn lại (Cụm động từ khuyết thiếu ở thể bị động)\n\nCấu trúc:\n* postpone something (v): trì hoãn, dời thời gian tổ chức sự kiện sang lúc khác\n* Mệnh đề 1, so + Mệnh đề 2: cấu trúc câu ghép dùng liên từ đẳng lập \"so\" để chỉ kết quả"
