          "explanation": "Cần một đại từ quan hệ thay thế cho danh từ chỉ người 'The obstetrics nurses' làm chủ ngữ cho mệnh đề quan hệ ('are working'). 'who' là đại từ quan hệ chỉ người hợp lý nhất.",
          "analysis": "Phân tích câu:\n* The obstetrics nurses: Đội ngũ các y tá thuộc chuyên khoa sản (Cụm danh từ số nhiều làm chủ ngữ chính)\n* who are working under Dorothy Caramella: những người hiện đang làm việc dưới sự quản lý của bà Dorothy Caramella (Mệnh đề quan hệ xác định bắt đầu bằng đại từ chủ ngữ who)\n* will now be working: kể từ nay sẽ chuyển sang làm việc (Cụm động từ chia thì tương lai tiếp diễn kèm trạng từ thời gian)\n* for Pierre Cocteau: dưới quyền phụ trách của ông Pierre Cocteau (Cụm giới từ chỉ người quản lý mới)\n\nCấu trúc:\n* work under somebody (v phr): làm việc dưới sự chỉ đạo, giám sát trực tiếp của cấp trên nào.\n* N(chỉ người) + who + V (cấu trúc mệnh đề quan hệ): dùng đại từ quan hệ who làm chủ ngữ thay thế cho danh từ chỉ người \"The obstetrics nurses\" đứng ngay trước đó."
