          "analysis": "Phân tích cấu trúc câu theo cụm:\n* The area surrounding the new Furniture Vine headquarters: Khu vực bao quanh trụ sở chính mới của Furniture Vine (Cụm chủ ngữ có phân từ V-ing rút gọn mệnh đề quan hệ)\n* is covered by dense forest: được bao phủ bởi rừng rậm (Vị ngữ bị động).\n\nCấu trúc ngữ pháp cần nhớ:\n* the area surrounding + Noun: khu vực bao quanh nơi nào đó (rút gọn của 'the area which surrounds...')."
