          "analysis": "Phân tích cấu trúc câu theo cụm:\n* Please direct inquiries to the appropriate person: Vui lòng gửi các câu hỏi đến người phụ trách phù hợp (Câu mệnh lệnh)\n* listed in our updated staff directory: được liệt kê trong danh bạ nhân viên đã cập nhật của chúng tôi (Cụm phân từ rút gọn bổ nghĩa cho person).\n\nCấu trúc ngữ pháp cần nhớ:\n* direct inquiries/questions to somebody: chuyển/gửi câu hỏi tới ai.\n* updated + Noun: (tài liệu/danh sách) đã được cập nhật mới nhất."
