          "explanation": "Chủ ngữ của mệnh đề phụ là 'his train' (chuyến tàu của ông ấy), phía trước chỗ trống có động từ to be 'was' và trạng từ 'unexpectedly'. Chuyến tàu chịu tác động bị làm trễ/hoãn nên động từ phải chia ở thể bị động quá khứ đơn: 'was unexpectedly delayed'. Do đó, quá khứ phân từ (C) delayed là đáp án đúng.",
          "analysis": "Phân tích cấu trúc câu theo cụm:\n* Mr. Zasio will need to reschedule his appointment today: Ông Zasio sẽ cần phải dời lịch hẹn của mình vào hôm nay (Mệnh đề chính)\n* as his train was unexpectedly delayed: bởi vì chuyến tàu của ông ấy đã bị trì hoãn một cách bất ngờ (Mệnh đề chỉ nguyên nhân).\n\nCấu trúc ngữ pháp cần nhớ:\n* be delayed: bị hoãn, bị chậm trễ.\n* as = because = since: bởi vì."
