          "analysis": "Phân tích câu:\n* Mr. Akagi: Ông Akagi (Chủ ngữ chính của câu)\n* was unable to buy tickets: đã không thể mua được vé (Động từ to be + tính từ + to-V + tân ngữ)\n* for the concert: cho buổi hòa nhạc (Cụm giới từ chỉ mục đích)\n* because it was sold out: bởi vì nó đã được bán hết vé (Mệnh đề trạng ngữ chỉ nguyên nhân ở thể bị động)\n\nCấu trúc:\n* be unable to + V (adj phr): không thể làm gì (tương đương cannot/could not + V).\n* be sold out (v phr): được bán hết sạch, cháy vé."
