          "explanation": "Sau động từ 'follow' (tuân theo) và tính từ 'specific', từ 'cleaning' đóng vai trò danh từ ghép bổ nghĩa cho chỗ trống. Ta cần một danh từ số nhiều đếm được để chỉ 'các quy trình/thủ tục'. Danh từ 'procedures' (các quy trình) tạo thành cụm danh từ chuẩn 'cleaning procedures' (các quy trình dọn dẹp vệ sinh).",
          "analysis": "Phân tích câu:\n* Zhang Cleaning takes great care: Công ty vệ sinh Zhang hết sức chú trọng (Chủ ngữ + Cụm động từ chia thì hiện tại đơn)\n* to ensure that: nhằm đảm bảo rằng (Động từ nguyên mẫu chỉ mục đích + Liên từ dẫn mệnh đề danh ngữ)\n* all its employees follow: toàn bộ nhân viên của công ty đều tuân thủ (Cụm danh từ làm chủ ngữ + Động từ chính)\n* specific cleaning procedures: các quy trình làm sạch cụ thể (Tính từ + Cụm danh từ ghép số nhiều làm tân ngữ)\n\nCấu trúc:\n* take great care to do sth (v phr): hết sức cẩn trọng / chú tâm để làm gì\n* follow specific procedures (v phr): tuân thủ các quy trình cụ thể"
