          "questionTranslation": "Công viên Nordel sẽ mở cửa đón mùa du lịch một khi nhiệt độ trung bình ban ngày đạt ít nhất 15 độ.",
          "explanation": "Đứng trước một con số chỉ mức nhiệt độ cụ thể ('15 degrees'), ta cần một trạng từ chỉ mức tối thiểu/ngưỡng điều kiện. Cụm 'at least' (ít nhất, tối thiểu) hoàn toàn phù hợp để diễn đạt nhiệt độ phải đạt tối thiểu 15 độ thì công viên mới mở cửa.",
          "analysis": "Phân tích câu:\n* Nordel Park will open: Công viên Nordel sẽ mở cửa (Chủ ngữ + Động từ chia thì tương lai đơn)\n* for the season: để đón mùa hoạt động mới (Cụm giới từ chỉ mục đích / thời gian)\n* once average daytime temperatures reach: một khi nhiệt độ trung bình ban ngày chạm ngưỡng (Liên từ chỉ điều kiện thời gian + Cụm danh từ làm chủ ngữ + Động từ)\n* at least 15 degrees: ít nhất là 15 độ (Cụm trạng từ chỉ mức tối thiểu + Danh từ chỉ nhiệt độ)\n\nCấu trúc:\n* once + S + V (hiện tại đơn), S + will + V: một khi... thì sẽ...\n* at least + số lượng (adv phr): ít nhất, tối thiểu là bao nhiêu"
