          "explanation": "Cấu trúc 'so + adj/adv + that' (quá ... đến nỗi mà ...). Vì phía trước chỗ trống là nội động từ thường 'laughed' (đã cười), ta cần một trạng từ ở dạng nguyên cấp để bổ nghĩa cho động từ đó. Do vậy, trạng từ 'loudly' (D) là đáp án đúng.",
          "analysis": "Phân tích cấu trúc câu theo cụm:\n* The audience laughed so loudly during the play: Khán giả đã cười quá to trong suốt vở kịch (Mệnh đề chính với cấu trúc so + adv)\n* that some of the actors’ lines were drowned out: đến mức một số lời thoại của diễn viên bị tiếng ồn lấn át mất (Mệnh đề chỉ kết quả).\n\nCấu trúc ngữ pháp cần nhớ:\n* V + so + adv + that + S + V: làm gì đó đến mức mà...\n* drown out (cụm động từ): át đi, lấn át âm thanh khác."
