          "explanation": "Phía sau chỗ trống là cụm vị ngữ 'finally arrived on Friday morning' (cuối cùng đã đến vào sáng thứ Sáu) đang thiếu chủ ngữ. Do đó, chỗ trống cần một đại từ quan hệ làm chủ ngữ thay thế cho cụm danh từ chỉ vật 'the shipment of gift boxes'. Trong bốn phương án, chỉ có đại từ quan hệ 'that' (A) đảm nhận được chức năng này.",
          "analysis": "Phân tích cấu trúc câu theo cụm:\n* The Blakewood store had been waiting for the shipment of gift boxes: Cửa hàng Blakewood đã chờ đợi lô hàng hộp quà (Mệnh đề chính chia thì quá khứ hoàn thành tiếp diễn)\n* that finally arrived on Friday morning: lô hàng mà cuối cùng đã tới vào sáng thứ Sáu (Mệnh đề quan hệ bổ nghĩa cho the shipment).\n\nCấu trúc ngữ pháp cần nhớ:\n* Đại từ quan hệ 'that' (hoặc 'which') làm chủ ngữ cho danh từ chỉ sự vật đứng trước."
